CREATE TABLE app_user (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,
 role VARCHAR(10) NOT NULL,CHECK(role IN ('BUYER','SELLER','ADMIN'))
);
CREATE TABLE venue (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL,name VARCHAR(255) NOT NULL,FOREIGN KEY(owner_id) REFERENCES app_user(id));
CREATE TABLE seat(id BIGINT AUTO_INCREMENT PRIMARY KEY,venue_id BIGINT NOT NULL,label VARCHAR(30) NOT NULL,row_label VARCHAR(2) NOT NULL,seat_number INT NOT NULL,UNIQUE(venue_id,row_label,seat_number),FOREIGN KEY(venue_id) REFERENCES venue(id));
ALTER TABLE performance ADD COLUMN owner_id BIGINT NULL,ADD COLUMN venue_id BIGINT NULL,ADD COLUMN description TEXT NULL,ADD CONSTRAINT fk_perf_owner FOREIGN KEY(owner_id) REFERENCES app_user(id),ADD CONSTRAINT fk_perf_venue FOREIGN KEY(venue_id) REFERENCES venue(id);
CREATE TABLE performance_sale(performance_id BIGINT PRIMARY KEY,status VARCHAR(12) NOT NULL DEFAULT 'PREPARING',starts_at TIMESTAMP(6) NULL,ends_at TIMESTAMP(6) NULL,FOREIGN KEY(performance_id) REFERENCES performance(id),CHECK(status IN ('PREPARING','OPEN','CLOSED')),CHECK((starts_at IS NULL AND ends_at IS NULL) OR(starts_at IS NOT NULL AND ends_at IS NOT NULL AND ends_at>starts_at)));
CREATE TABLE performance_session(id BIGINT AUTO_INCREMENT PRIMARY KEY,performance_id BIGINT NOT NULL,starts_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(performance_id) REFERENCES performance(id),INDEX(performance_id));
CREATE TABLE seat_hold(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,session_id BIGINT NOT NULL,expires_at TIMESTAMP(6) NOT NULL,status VARCHAR(12) NOT NULL,total_krw BIGINT NOT NULL,CHECK(total_krw>=0),CHECK(status IN ('ACTIVE','RELEASED','EXPIRED','CONFIRMED')),FOREIGN KEY(user_id) REFERENCES app_user(id),FOREIGN KEY(session_id) REFERENCES performance_session(id),INDEX(user_id),INDEX(expires_at));
CREATE TABLE session_seat(session_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,price_krw BIGINT NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'AVAILABLE',hold_id BIGINT NULL,PRIMARY KEY(session_id,seat_id),FOREIGN KEY(session_id) REFERENCES performance_session(id),FOREIGN KEY(seat_id) REFERENCES seat(id),FOREIGN KEY(hold_id) REFERENCES seat_hold(id),CHECK(price_krw>=0),CHECK(status IN ('AVAILABLE','HELD','BOOKED')),CHECK((status='AVAILABLE' AND hold_id IS NULL) OR(status IN ('HELD','BOOKED') AND hold_id IS NOT NULL)),INDEX(hold_id));
CREATE TABLE hold_seat(hold_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,PRIMARY KEY(hold_id,seat_id),FOREIGN KEY(hold_id) REFERENCES seat_hold(id),FOREIGN KEY(seat_id) REFERENCES seat(id));
CREATE TABLE reservation(id BIGINT AUTO_INCREMENT PRIMARY KEY,hold_id BIGINT NOT NULL UNIQUE,user_id BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(hold_id) REFERENCES seat_hold(id),FOREIGN KEY(user_id) REFERENCES app_user(id),INDEX(user_id));
CREATE TABLE mock_payment(id BIGINT AUTO_INCREMENT PRIMARY KEY,hold_id BIGINT NOT NULL UNIQUE,status VARCHAR(10) NOT NULL,amount_krw BIGINT NOT NULL,reservation_id BIGINT NULL UNIQUE,FOREIGN KEY(hold_id) REFERENCES seat_hold(id),FOREIGN KEY(reservation_id) REFERENCES reservation(id),CHECK(status IN ('SUCCESS','FAILED')),CHECK(amount_krw>=0));
CREATE TABLE idempotency(user_id BIGINT NOT NULL,operation VARCHAR(100) NOT NULL,idempotency_key VARCHAR(128) COLLATE utf8mb4_bin NOT NULL,fingerprint CHAR(64) NOT NULL,response_json JSON NULL,PRIMARY KEY(user_id,operation,idempotency_key),FOREIGN KEY(user_id) REFERENCES app_user(id));
